#!/usr/bin/env node
// Collect the highest-star public gh-aw adopters and snapshot their AW source/lock files.
// Implements top-public-aw-repositories + retrieve-public-aw-workflows. Zero dependencies.
//
// Usage: node collect.mjs [--exclude OWNER/REPO]... [--no-default-exclude] [--count N] [--out DIR] [--owner OWNER] [--code-pages N] [--repo-pages N]
//                         [--from-search PREV_OUT/search-candidates.json]
// Requires `gh` authenticated for github.com (metadata only). Raw bytes are fetched anonymously.
// Downloaded content is treated as data: never executed, compiled, or followed.

import { execFile } from "node:child_process";
import { createHash } from "node:crypto";
import { mkdir, readFile, writeFile } from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { promisify } from "node:util";

const execFileP = promisify(execFile);
const MAX_BYTES = 8 * 1024 * 1024;
const CONCURRENCY = 4;
const NAME_RE = /^[A-Za-z0-9_.-]+$/;
const FILE_RE = /^[A-Za-z0-9_.@+-]+$/;

export const CODE_QUERIES = [
  '"github/gh-aw" path:.github/workflows extension:yml',
  '"github/gh-aw-actions" path:.github/workflows extension:yml',
  '"githubnext/gh-aw" path:.github/workflows extension:yml',
];
export const REPO_QUERIES = [
  '"gh-aw" in:readme is:public fork:false stars:>0',
  '"github agentic workflows" in:readme is:public fork:false stars:>0',
  "topic:gh-aw is:public fork:false stars:>0",
];

const nowIso = () => new Date().toISOString().replace(/\.\d+Z$/, "Z");
const sleep = ms => new Promise(r => setTimeout(r, ms));

export class HostFailure extends Error {}

export function gitBlobId(buf) {
  return createHash("sha1").update(`blob ${buf.length}\0`).update(buf).digest("hex");
}

// Only the leading YAML comment block counts; matches inside scripts or values are ignored.
export function lockEvidence(text) {
  const evidence = [];
  for (const line of text.replace(/^\uFEFF/, "").split(/\r?\n/)) {
    if (!line.startsWith("#")) break;
    if (/automatically generated by gh-aw/i.test(line)) evidence.push("generated-header");
    const m = line.match(/^#\s*gh-aw-metadata:\s*(\{.*\})\s*$/);
    if (m) {
      try {
        const meta = JSON.parse(m[1]);
        if (typeof meta.compiler_version === "string" && meta.compiler_version) {
          evidence.push(`gh-aw-metadata compiler_version=${meta.compiler_version}`);
        }
      } catch {
        // malformed compiler record is not evidence
      }
    }
  }
  return [...new Set(evidence)];
}

export function hasFrontmatter(text) {
  const lines = text.replace(/^\uFEFF/, "").split(/\r?\n/);
  return lines[0]?.trim() === "---" && lines.slice(1).some(l => l.trim() === "---");
}

export function isSafeWorkflowEntry(entry) {
  return entry.type === "blob" && (entry.mode === "100644" || entry.mode === "100755") && FILE_RE.test(entry.path) && entry.path !== "." && entry.path !== "..";
}

export function sortCandidates(list) {
  return [...list].sort((a, b) => b.stars - a.stars || a.full_name.toLowerCase().localeCompare(b.full_name.toLowerCase()));
}

async function pool(items, fn, limit = CONCURRENCY) {
  const out = new Array(items.length);
  let i = 0;
  await Promise.all(
    Array.from({ length: Math.min(limit, items.length) }, async () => {
      while (i < items.length) {
        const k = i++;
        out[k] = await fn(items[k], k);
      }
    })
  );
  return out;
}

async function gh(apiPath, params = {}) {
  const args = ["api", "--hostname", "github.com", "-X", "GET", "-i", apiPath];
  for (const [k, v] of Object.entries(params)) args.push("-f", `${k}=${v}`);
  let stdout;
  try {
    ({ stdout } = await execFileP("gh", args, { maxBuffer: 64 * 1024 * 1024 }));
  } catch (err) {
    stdout = err.stdout ?? "";
  }
  const sep = stdout.indexOf("\r\n\r\n") >= 0 ? "\r\n\r\n" : "\n\n";
  const idx = stdout.indexOf(sep);
  const head = idx >= 0 ? stdout.slice(0, idx) : stdout;
  const body = idx >= 0 ? stdout.slice(idx + sep.length) : "";
  const status = Number(head.match(/^HTTP\/\S+\s+(\d+)/)?.[1] ?? 0);
  let data = null;
  try {
    data = body.trim() ? JSON.parse(body) : null;
  } catch {
    data = null;
  }
  const rateLimited = status === 429 || (status === 403 && (/rate limit/i.test(body) || /^x-ratelimit-remaining:\s*0\s*$/im.test(head)));
  if (status === 401) throw new HostFailure(`${apiPath}: HTTP 401`);
  return { status, data, rateLimited };
}

// One GraphQL call replaces several REST calls per repository; returns { data, errors, ok }.
async function graphql(query) {
  let stdout = "";
  try {
    ({ stdout } = await execFileP("gh", ["api", "--hostname", "github.com", "graphql", "-f", `query=${query}`], { maxBuffer: 128 * 1024 * 1024 }));
  } catch (err) {
    stdout = err.stdout ?? "";
  }
  try {
    const parsed = JSON.parse(stdout);
    const errors = parsed.errors ?? [];
    if (errors.some(e => e.type === "RATE_LIMITED")) throw new HostFailure("GraphQL rate limited");
    return { ok: Boolean(parsed.data), data: parsed.data ?? {}, errors };
  } catch (err) {
    if (err instanceof HostFailure) throw err;
    return { ok: false, data: {}, errors: [{ message: "non-JSON GraphQL response (likely timeout)" }] };
  }
}

const gqlString = s => JSON.stringify(s);

// Batch aliased repository queries; halve the batch on transport failure so one heavy repo cannot sink the rest.
async function graphqlRepos(items, fragment, batchSize) {
  const results = new Map();
  const run = async batch => {
    const body = batch.map(([owner, repo], i) => `r${i}: repository(owner: ${gqlString(owner)}, name: ${gqlString(repo)}) { ${fragment} }`).join("\n");
    const res = await graphql(`{ ${body} }`);
    if (!res.ok && batch.length > 1) {
      const mid = Math.ceil(batch.length / 2);
      await run(batch.slice(0, mid));
      await run(batch.slice(mid));
      return;
    }
    batch.forEach(([owner, repo], i) => {
      const node = res.data[`r${i}`];
      const err = res.errors.find(e => e.path?.[0] === `r${i}`) ?? (!res.ok ? res.errors[0] : null);
      results.set(`${owner}/${repo}`, node ? { node } : { error: err?.type ?? err?.message ?? "not returned" });
    });
  };
  const batches = [];
  for (let i = 0; i < items.length; i += batchSize) batches.push(items.slice(i, i + batchSize));
  await pool(batches, run, 2);
  return results;
}

const META_FRAGMENT = "nameWithOwner url isPrivate isFork visibility stargazerCount isArchived owner { login } defaultBranchRef { name }";
const TREE_FRAGMENT =
  'defaultBranchRef { name target { ... on Commit { oid tree { oid } gh: file(path: ".github") { type } wf: file(path: ".github/workflows") { type object { ... on Tree { entries { name type mode oid size } } } } } } }';
const MODE_NAMES = { 33188: "100644", 33261: "100755", 40960: "120000", 57344: "160000", 16384: "040000" };

// REST fallback for repositories whose workflow tree is too large for a GraphQL response.
// Returns the same shape as TREE_FRAGMENT so retrieve() has one code path.
async function restTree(owner, repo, branch) {
  const commit = await gh(`repos/${owner}/${repo}/commits/${encodeURIComponent(branch)}`);
  if (commit.rateLimited) throw new HostFailure("core API rate limited");
  if (commit.status !== 200 || !commit.data?.sha) return { error: `REST commit HTTP ${commit.status}` };
  const target = { oid: commit.data.sha, tree: { oid: commit.data.commit.tree.sha }, gh: null, wf: null };
  let tree = target.tree.oid;
  for (const part of [".github", "workflows"]) {
    const t = await gh(`repos/${owner}/${repo}/git/trees/${tree}`);
    if (t.rateLimited) throw new HostFailure("core API rate limited");
    if (t.status !== 200 || !t.data || t.data.truncated) return { error: `REST tree ${part} HTTP ${t.status}${t.data?.truncated ? " truncated" : ""}` };
    const e = t.data.tree.find(x => x.path === part);
    if (!e || e.type !== "tree") return { node: { defaultBranchRef: { name: branch, target } } };
    if (part === ".github") target.gh = { type: "tree" };
    tree = e.sha;
  }
  const wf = await gh(`repos/${owner}/${repo}/git/trees/${tree}`);
  if (wf.rateLimited) throw new HostFailure("core API rate limited");
  if (wf.status !== 200 || !wf.data || wf.data.truncated) return { error: `REST workflows tree HTTP ${wf.status}` };
  const modes = Object.fromEntries(Object.entries(MODE_NAMES).map(([k, v]) => [v, Number(k)]));
  target.wf = { type: "tree", object: { entries: wf.data.tree.map(e => ({ name: e.path, type: e.type, mode: modes[e.mode] ?? e.mode, oid: e.sha, size: e.size })) } };
  return { node: { defaultBranchRef: { name: branch, target } } };
}

let activeDownloads = 0;
const waiters = [];
async function withDownloadSlot(fn) {
  while (activeDownloads >= CONCURRENCY) await new Promise(r => waiters.push(r));
  activeDownloads++;
  try {
    return await fn();
  } finally {
    activeDownloads--;
    waiters.shift()?.();
  }
}

function rawGet(owner, repo, sha, relPath) {
  return withDownloadSlot(() => rawGetUnlimited(owner, repo, sha, relPath));
}

async function rawGetUnlimited(owner, repo, sha, relPath) {
  const url = `https://raw.githubusercontent.com/${owner}/${repo}/${sha}/${relPath.split("/").map(encodeURIComponent).join("/")}`;
  const res = await fetch(url, { signal: AbortSignal.timeout(90_000), headers: { "user-agent": "gh-aw-corpus-collector" } });
  if (!res.ok) throw new Error(`HTTP ${res.status}`);
  const chunks = [];
  let n = 0;
  for await (const chunk of res.body) {
    n += chunk.length;
    if (n > MAX_BYTES) throw new Error("exceeds 8 MiB");
    chunks.push(chunk);
  }
  return Buffer.concat(chunks);
}

function parseArgs(argv) {
  // github/gh-aw is the compiler repo itself (available locally), not an external adopter.
  const opts = { count: 100, out: null, owner: null, codePages: 10, repoPages: 2, fromSearch: null, exclude: ["github/gh-aw"] };
  for (let i = 0; i < argv.length; i++) {
    const [k, v] = [argv[i], argv[i + 1]];
    if (k === "--count") (opts.count = Number(v)), i++;
    else if (k === "--out") (opts.out = v), i++;
    else if (k === "--owner") (opts.owner = v), i++;
    else if (k === "--code-pages") (opts.codePages = Number(v)), i++;
    else if (k === "--repo-pages") (opts.repoPages = Number(v)), i++;
    else if (k === "--from-search") (opts.fromSearch = v), i++;
    else if (k === "--exclude") (opts.exclude.push(v), i++);
    else if (k === "--no-default-exclude") opts.exclude = opts.exclude.filter(x => x !== "github/gh-aw");
    else throw new Error(`unknown argument: ${k}`);
  }
  if (!opts.out) {
    const stamp = nowIso().replace(/[-:]/g, "");
    opts.out = path.join(process.env.TMPDIR || "/tmp", "aw-top-public", stamp);
  }
  if (opts.owner && !NAME_RE.test(opts.owner)) throw new Error("invalid --owner");
  return opts;
}

async function main() {
  const opts = parseArgs(process.argv.slice(2));
  const OUT = path.resolve(opts.out);
  await mkdir(OUT, { recursive: true });
  const writeJson = (name, obj) => writeFile(path.join(OUT, name), JSON.stringify(obj, null, 2) + "\n");
  const log = msg => process.stderr.write(`${msg}\n`);
  log(`[out] ${OUT}`);

  const coverage = { started_at: nowIso(), requested_count: opts.count, owner_restriction: opts.owner, excluded_repositories: opts.exclude, per_page: 100, queries: [] };
  const found = new Map();
  let privateSearchItems = 0;
  const failures = [];
  let hostStop = null;

  async function search(kind, q, budget) {
    const query = opts.owner ? `${q} user:${opts.owner}` : q;
    const rec = { kind, query, page_budget: budget, pages_fetched: 0, items: 0, total_count: null, incomplete_results: false, truncated_by_budget: false, truncated_by_1000_cap: false, started_at: nowIso(), failures: [] };
    for (let page = 1; page <= budget; page++) {
      const params = { q: query, per_page: 100, page };
      if (kind === "repositories") Object.assign(params, { sort: "stars", order: "desc" });
      let res;
      // Search secondary limits reset within a minute; wait once rather than evading them.
      for (let attempt = 0; attempt < 2; attempt++) {
        res = await gh(`search/${kind}`, params);
        if (!res.rateLimited) break;
        log(`[search] rate limited; waiting 65s`);
        await sleep(65_000);
      }
      if (res.rateLimited) throw new HostFailure(`search/${kind}: rate limited`);
      if (res.status !== 200 || !res.data) {
        rec.failures.push({ page, status: res.status });
        break;
      }
      rec.pages_fetched++;
      rec.total_count = res.data.total_count;
      rec.incomplete_results ||= Boolean(res.data.incomplete_results);
      const items = res.data.items ?? [];
      rec.items += items.length;
      for (const it of items) {
        const r = kind === "code" ? it.repository : it;
        if (r?.private !== false) {
          privateSearchItems++;
          continue;
        }
        if (!found.has(r.full_name.toLowerCase())) found.set(r.full_name.toLowerCase(), r.full_name);
      }
      if (items.length < 100) break;
      if (page === budget) rec.truncated_by_budget = true;
      await sleep(kind === "code" ? 6500 : 2100); // code search: 10/min; search: 30/min
    }
    rec.truncated_by_1000_cap = (rec.total_count ?? 0) > 1000;
    rec.finished_at = nowIso();
    coverage.queries.push(rec);
    log(`[search] ${kind} ${JSON.stringify(query)} total=${rec.total_count} pages=${rec.pages_fetched} unique=${found.size}`);
  }

  if (opts.fromSearch) {
    // Reuse a previous run's search results (public names only) to skip slow code-search pacing.
    const prev = JSON.parse(await readFile(path.resolve(opts.fromSearch), "utf8"));
    for (const n of prev.public_full_names) if (/^[^/]+\/[^/]+$/.test(n)) found.set(n.toLowerCase(), n);
    Object.assign(coverage, { reused_from: opts.fromSearch, queries: prev.coverage?.queries ?? [] });
    privateSearchItems = prev.coverage?.excluded_aggregate?.private_or_unverified_search_items ?? 0;
    log(`[search] reused ${found.size} candidates from ${opts.fromSearch}`);
  } else {
    try {
      for (const q of CODE_QUERIES) await search("code", q, opts.codePages);
      for (const q of REPO_QUERIES) await search("repositories", q, opts.repoPages);
    } catch (err) {
      if (!(err instanceof HostFailure)) throw err;
      hostStop = err.message;
      failures.push({ repository: null, stage: "search", status: err.message, incomplete: true, kind: "host-wide" });
    }
  }
  coverage.excluded_aggregate = { private_or_unverified_search_items: privateSearchItems };
  coverage.unique_public_candidates_from_search = found.size;
  await writeJson("search-coverage.json", coverage);
  await writeJson("search-candidates.json", { generated_at: nowIso(), coverage, public_full_names: [...found.values()] });

  const verifyExcluded = {};
  const bump = k => {
    verifyExcluded[k] = (verifyExcluded[k] ?? 0) + 1;
    return null;
  };
  const names = [];
  for (const full of found.values()) {
    const [owner, repo] = full.split("/");
    if (NAME_RE.test(owner) && NAME_RE.test(repo)) names.push([owner, repo]);
    else bump("invalid_name");
  }
  let metas = new Map();
  if (!hostStop) {
    try {
      metas = await graphqlRepos(names, META_FRAGMENT, 50);
    } catch (err) {
      if (!(err instanceof HostFailure)) throw err;
      hostStop = err.message;
      failures.push({ repository: null, stage: "metadata", status: err.message, incomplete: true, kind: "host-wide" });
    }
  }
  const verified = [...metas.values()].map(({ node: d, error }) => {
    if (!d) {
      // NOT_FOUND covers deleted, renamed-away, and private repos; keep only the aggregate.
      if (error !== "NOT_FOUND") failures.push({ repository: null, stage: "metadata", status: error, incomplete: true, kind: "access-or-api-error" });
      return bump(error === "NOT_FOUND" ? "not_found_or_private" : "metadata_error");
    }
    if (d.isPrivate !== false || (d.visibility != null && d.visibility !== "PUBLIC")) return bump("private_or_unverified");
    if (d.isFork !== false) return bump("fork");
    if (!(d.stargazerCount > 0)) return bump("no_stars");
    if (!d.defaultBranchRef) return bump("empty_repository");
    if (opts.exclude.some(x => x.toLowerCase() === d.nameWithOwner.toLowerCase())) return bump("excluded_by_request");
    if (opts.owner && d.owner?.login?.toLowerCase() !== opts.owner.toLowerCase()) return bump("owner_mismatch");
    return { full_name: d.nameWithOwner, stars: d.stargazerCount, stars_observed_at: nowIso(), default_branch: d.defaultBranchRef.name, archived: Boolean(d.isArchived), html_url: d.url };
  });
  const dedup = new Map();
  for (const c of verified) if (c && !dedup.has(c.full_name.toLowerCase())) dedup.set(c.full_name.toLowerCase(), c);
  const candidates = sortCandidates([...dedup.values()]).map((c, i) => ({ ...c, candidate_rank: i + 1 }));
  await writeJson("candidates.json", { generated_at: nowIso(), ordering: "stars desc, full_name asc (case-insensitive)", excluded_aggregate: verifyExcluded, candidates });
  log(`[verify] candidates=${candidates.length} excluded=${JSON.stringify(verifyExcluded)}`);

  async function retrieve(c, treeResult) {
    const [owner, repo] = c.full_name.split("/");
    const man = {
      full_name: c.full_name, stars: c.stars, stars_observed_at: c.stars_observed_at, archived: c.archived, default_branch: c.default_branch,
      requested_scope: "gh-aw source .md + .lock.yml directly under .github/workflows/",
      retrieved_at: nowIso(), commit: null, tree_sha: null, adoption_evidence: [], files: [], missing_sources: [], rejected: [], failures: [], status: null,
    };
    const fail = (stage, status) => (man.failures.push({ stage, status }), (man.status = "failed"), man);
    if (!treeResult?.node && treeResult?.error !== "NOT_FOUND") treeResult = await restTree(owner, repo, c.default_branch);
    const target = treeResult?.node?.defaultBranchRef?.target;
    if (!target?.oid) return fail("commit+tree", treeResult?.error ?? "no default branch commit");
    if (treeResult.node.defaultBranchRef.name !== c.default_branch) man.default_branch_at_pin = treeResult.node.defaultBranchRef.name;
    const sha = target.oid;
    man.commit = sha;
    man.tree_sha = target.tree.oid;
    if (target.gh?.type !== "tree") return Object.assign(man, { status: "no-confirmed-aw", note: "no .github directory" });
    if (target.wf?.type !== "tree" || !target.wf.object) return Object.assign(man, { status: "no-confirmed-aw", note: "no workflows directory" });

    const blobs = new Map();
    for (const raw of target.wf.object.entries) {
      const e = { path: raw.name, type: raw.type, mode: MODE_NAMES[raw.mode] ?? String(raw.mode), sha: raw.oid, size: raw.size };
      if (!e.path.endsWith(".lock.yml") && !e.path.endsWith(".md")) continue;
      if (!isSafeWorkflowEntry(e)) man.rejected.push({ path: e.path, reason: `unsafe entry type=${e.type} mode=${e.mode}` });
      else if ((e.size ?? 0) > MAX_BYTES) man.rejected.push({ path: e.path, reason: "exceeds 8 MiB" });
      else blobs.set(e.path, e);
    }
    const fetchBlob = async name => {
      const e = blobs.get(name);
      try {
        const buf = await rawGet(owner, repo, sha, `.github/workflows/${name}`);
        if (buf.length !== e.size || gitBlobId(buf) !== e.sha) return { name, err: "size/blob-id mismatch" };
        return { name, buf };
      } catch (err) {
        return { name, err: `download: ${err.message}` };
      }
    };
    const kept = new Map();
    const locks = [...blobs.keys()].filter(n => n.endsWith(".lock.yml")).sort();
    for (const r of await pool(locks, fetchBlob)) {
      if (r.err) {
        man.failures.push({ stage: "download", path: r.name, status: r.err });
        continue;
      }
      const ev = lockEvidence(r.buf.toString("utf8"));
      if (!ev.length) {
        man.rejected.push({ path: r.name, reason: "no gh-aw generation evidence in header" });
        continue;
      }
      man.adoption_evidence.push({ path: `.github/workflows/${r.name}`, indicators: ev });
      kept.set(r.name, { kind: "aw-lock", buf: r.buf });
    }
    const sources = [...kept.keys()].map(n => n.replace(/\.lock\.yml$/, ".md"));
    man.missing_sources = sources.filter(s => !blobs.has(s)).map(s => `.github/workflows/${s}`);
    for (const r of await pool(sources.filter(s => blobs.has(s)), fetchBlob)) {
      if (r.err) man.failures.push({ stage: "download", path: r.name, status: r.err });
      else if (!hasFrontmatter(r.buf.toString("utf8"))) man.rejected.push({ path: r.name, reason: "paired source lacks frontmatter delimiters" });
      else kept.set(r.name, { kind: "aw-source", buf: r.buf });
    }
    const dir = path.join(OUT, "repos", owner, repo, ".github", "workflows");
    if (kept.size) await mkdir(dir, { recursive: true });
    for (const [name, { kind, buf }] of [...kept].sort(([a], [b]) => a.localeCompare(b))) {
      const local = path.join(dir, name);
      if (!local.startsWith(OUT + path.sep)) throw new Error("path escape");
      await writeFile(local, buf);
      const pair = kind === "aw-lock" ? name.replace(/\.lock\.yml$/, ".md") : name.replace(/\.md$/, ".lock.yml");
      man.files.push({
        path: `.github/workflows/${name}`, kind, bytes: buf.length, git_blob_id: blobs.get(name).sha,
        sha256: createHash("sha256").update(buf).digest("hex"), local_path: path.relative(OUT, local),
        source_url: `https://github.com/${owner}/${repo}/blob/${sha}/.github/workflows/${encodeURIComponent(name)}`,
        paired_path: kept.has(pair) ? `.github/workflows/${pair}` : null,
      });
    }
    man.status = man.adoption_evidence.length ? (man.failures.length ? "partial" : "complete") : man.failures.length ? "failed" : "no-confirmed-aw";
    return man;
  }

  const selected = [];
  const nonAdopters = [];
  const unselectedAdopters = [];
  let visited = 0;
  try {
    while (!hostStop && selected.length < opts.count && visited < candidates.length) {
      // Visit in star order; over-fetch slightly since some candidates are non-adopters.
      const batch = candidates.slice(visited, visited + Math.max(CONCURRENCY, Math.min(40, opts.count - selected.length + 8)));
      visited += batch.length;
      const trees = await graphqlRepos(batch.map(c => c.full_name.split("/")), TREE_FRAGMENT, 10);
      const manifests = await pool(batch, c => retrieve(c, trees.get(c.full_name)));
      for (const [i, c] of batch.entries()) {
        const m = manifests[i];
        const mdir = path.join(OUT, "repos", ...c.full_name.split("/"));
        await mkdir(mdir, { recursive: true });
        await writeFile(path.join(mdir, "manifest.json"), JSON.stringify(m, null, 2) + "\n");
        for (const f of m.failures) failures.push({ repository: c.full_name, stage: f.stage, path: f.path ?? null, status: f.status, incomplete: true, kind: "access-or-download-error" });
        if ((m.status === "complete" || m.status === "partial") && selected.length < opts.count) selected.push({ c, m });
        else if (m.status === "complete" || m.status === "partial") unselectedAdopters.push(c.full_name);
        else if (m.status === "no-confirmed-aw") nonAdopters.push(c.full_name);
      }
      log(`[retrieve] visited=${visited}/${candidates.length} selected=${selected.length}`);
    }
  } catch (err) {
    if (!(err instanceof HostFailure)) throw err;
    hostStop = err.message;
    failures.push({ repository: null, stage: "retrieve", status: err.message, incomplete: true, kind: "host-wide" });
  }

  const rows = selected.map(({ c, m }, i) => ({
    rank: i + 1, candidate_rank: c.candidate_rank, full_name: c.full_name, stars: c.stars, stars_observed_at: c.stars_observed_at,
    default_branch: c.default_branch, archived: c.archived, commit: m.commit,
    adoption_evidence_paths: m.adoption_evidence.map(e => e.path),
    aw_source_count: m.files.filter(f => f.kind === "aw-source").length,
    aw_lock_count: m.files.filter(f => f.kind === "aw-lock").length,
    missing_source_count: m.missing_sources.length, snapshot_status: m.status,
    manifest: `repos/${c.full_name}/manifest.json`,
  }));
  await writeJson("repositories.json", { generated_at: nowIso(), requested: opts.count, selected: rows.length, candidates_visited: visited, host_stop: hostStop, confirmed_non_adopters: nonAdopters, unselected_adopters_beyond_count: unselectedAdopters, repositories: rows });
  const cols = ["rank", "candidate_rank", "full_name", "stars", "stars_observed_at", "default_branch", "archived", "commit", "adoption_evidence_paths", "aw_source_count", "aw_lock_count", "missing_source_count", "snapshot_status", "manifest"];
  const cell = v => (/[",\n]/.test(String(v)) ? `"${String(v).replace(/"/g, '""')}"` : String(v));
  await writeFile(path.join(OUT, "repositories.csv"), [cols.join(","), ...rows.map(r => cols.map(k => cell(Array.isArray(r[k]) ? r[k].join(";") : r[k])).join(","))].join("\n") + "\n");
  await writeJson("failures.json", { generated_at: nowIso(), failures });
  coverage.finished_at = nowIso();
  await writeJson("search-coverage.json", coverage);

  const summary = {
    out: OUT, selected: rows.length, requested: opts.count, candidates: candidates.length, visited, non_adopters: nonAdopters.length,
    star_range: rows.length ? [rows[0].stars, rows.at(-1).stars] : null,
    aw_sources: rows.reduce((s, r) => s + r.aw_source_count, 0), aw_locks: rows.reduce((s, r) => s + r.aw_lock_count, 0),
    partial: rows.filter(r => r.snapshot_status === "partial").length, failures: failures.length, host_stop: hostStop,
  };
  process.stdout.write(JSON.stringify(summary, null, 2) + "\n");
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  main().catch(err => {
    process.stderr.write(`${err.stack ?? err}\n`);
    process.exit(1);
  });
}
